*{box-sizing:border-box} :root{color-scheme:dark;--bg:#101713;--panel:#19221d;--panel2:#202b24;--line:#2e3b32;--text:#f4f4e9;--muted:#9ba99e;--lime:#c8f36a;--green:#244b37;--gold:#edc878;--red:#f18875} body{margin:0;background:radial-gradient(ellipse at 50% -20%,#263d2d 0%,var(--bg) 57%);color:var(--text);font-family:'IBM Plex Sans Arabic',system-ui,sans-serif;min-height:100vh} button,input,textarea{font:inherit}button{cursor:pointer} .app-shell{width:min(100% - 36px,1030px);margin:0 auto;padding:18px 0 25px}.topbar{display:flex;align-items:center;justify-content:space-between;margin-bottom:32px}.brand{display:flex;align-items:center;gap:10px;color:var(--text);font-size:17px;font-weight:700;text-decoration:none}.brand-light{font-weight:400;color:#b9c5bb}.brand-mark{width:32px;height:32px;border-radius:11px;background:var(--lime);color:#182218;display:grid;place-items:center;font-size:19px;box-shadow:0 3px 15px #c8f36a30}.icon-button,.reset-button{border:1px solid var(--line);background:#172019;color:#bdcbbf;border-radius:12px;width:42px;height:40px;font-size:20px}.intro-row{display:flex;justify-content:space-between;align-items:end;margin-bottom:20px;gap:12px}.eyebrow{font-size:11px;letter-spacing:.08em;color:var(--lime);margin:0 0 6px;font-weight:600}.intro-row h1{font-size:clamp(25px,4vw,36px);line-height:1.15;margin:0;font-weight:700;letter-spacing:-.04em}.subtitle{font-size:13px;color:var(--muted);margin:8px 0 0}.turn-chip{display:flex;align-items:center;gap:9px;padding:9px 13px;background:#1a271e;border:1px solid #334333;border-radius:100px;font-size:12px;white-space:nowrap}.turn-dot,.live-dot{display:inline-block;width:8px;height:8px;background:var(--lime);border-radius:50%;box-shadow:0 0 12px #c8f36a66}.scoreboard{display:grid;grid-template-columns:1fr auto 1fr;align-items:center;gap:15px;margin-bottom:13px}.player-card{display:flex;align-items:center;gap:10px;background:var(--panel);border:1px solid var(--line);border-radius:14px;padding:10px 13px;min-height:62px;transition:.2s}.player-card.active{border-color:#759b4b;box-shadow:inset 0 0 0 1px #93bd5550;background:#1d2b20}.right-card{direction:rtl}.player-avatar{width:34px;height:34px;display:grid;place-items:center;border-radius:11px;font-size:15px;font-weight:700}.avatar-one{background:#d9eeaa;color:#27371d}.avatar-two{background:#d7b79a;color:#35281e}.player-info{display:grid;gap:1px;min-width:0}.player-caption{font-size:10px;color:var(--muted)}.player-info strong{font-size:13px;white-space:nowrap}.group-tag{margin-inline-start:auto;border:1px solid #465246;color:#c5d0c3;padding:3px 8px;border-radius:20px;font-size:10px}.score-center{text-align:center;min-width:78px}.score-label{display:block;color:var(--muted);font-size:10px}.score-center strong{font-size:20px;line-height:1.2}.score-center i{color:#718074;font-size:14px;font-style:normal;padding:0 4px}.table-card{background:#1b241e;border:1px solid #354239;border-radius:18px;padding:12px;box-shadow:0 18px 55px #0005}.table-topline{display:flex;align-items:center;justify-content:space-between;padding:1px 5px 11px;font-size:11px}.game-status{display:flex;align-items:center;gap:8px;color:#c4d2c5}.live-dot{width:6px;height:6px}.game-mode{color:#9eab9e;border:1px solid #38463a;padding:3px 9px;border-radius:20px}.table-wrap{position:relative;overflow:hidden;border-radius:13px;background:#101912}.table-wrap canvas{display:block;width:100%;height:auto;aspect-ratio:1000/560;touch-action:none;cursor:crosshair}.table-footer{display:flex;align-items:center;gap:7px;padding:10px 5px 0;font-size:10px;color:var(--muted)}kbd{font:inherit;padding:2px 6px;background:#2c372e;border:1px solid #465044;border-radius:5px;color:#dbe5d8}.table-hint{margin-inline-start:auto;color:#8f9e91}.controls-card{display:flex;align-items:center;gap:15px;margin-top:12px;background:var(--panel);border:1px solid var(--line);border-radius:15px;padding:12px 14px}.aim-control{flex:1}.control-heading{display:flex;justify-content:space-between;align-items:center;font-size:12px;color:#c4d0c4}.control-heading strong{color:var(--lime);font-size:12px}input[type=range]{width:100%;height:5px;margin:12px 0 4px;accent-color:var(--lime);cursor:pointer}.range-labels{display:flex;justify-content:space-between;font-size:9px;color:#77857a}.shoot-button,.primary-button{background:var(--lime);border:0;border-radius:12px;color:#172019;font-weight:700;padding:11px 22px;display:inline-flex;align-items:center;justify-content:center;gap:8px;transition:transform .15s,filter .15s}.shoot-button{min-width:112px;font-size:14px}.shoot-button:hover,.primary-button:hover{filter:brightness(1.05);transform:translateY(-1px)}.shoot-button:disabled{opacity:.45;cursor:not-allowed;transform:none}.shoot-icon{transform:rotate(180deg);font-size:15px}.reset-button{width:42px;flex-shrink:0}.bottom-tools{display:flex;align-items:center;gap:13px;margin-top:13px}.assist-toggle{display:flex;align-items:center;gap:10px;flex:1;cursor:pointer;padding:9px 12px;border:1px solid var(--line);background:#19221d;border-radius:13px;min-height:54px}.assist-toggle input{position:absolute;opacity:0;pointer-events:none}.toggle-ui{width:34px;height:20px;border-radius:20px;background:#3a463d;position:relative;flex-shrink:0;transition:.2s}.toggle-ui:after{content:'';position:absolute;right:3px;top:3px;width:14px;height:14px;border-radius:50%;background:#c2cbbf;transition:.2s}.assist-toggle input:checked+.toggle-ui{background:#63863d}.assist-toggle input:checked+.toggle-ui:after{right:17px;background:#e5ffad}.assist-copy{display:grid;gap:1px}.assist-copy strong{font-size:11px}.assist-copy small{font-size:9px;color:var(--muted)}.assist-badge{margin-inline-start:auto;background:#35492b;color:#d5eba2;font-size:9px;padding:4px 8px;border-radius:20px}.friend-button,.secondary-button{color:#e5ece4;background:#202c24;border:1px solid #425247;border-radius:12px;padding:12px 15px;font-size:12px;font-weight:600;white-space:nowrap}.friend-button span{font-size:17px;color:var(--lime);vertical-align:-1px;margin-inline-end:5px}.fair-play-note{font-size:10px;color:#78877b;margin:9px 4px 0;line-height:1.6}footer{display:flex;align-items:center;justify-content:space-between;border-top:1px solid #253129;margin-top:17px;padding-top:13px;color:#768379;font-size:10px}.text-button{background:none;border:0;color:#bdc9bc;font-size:10px}.toast{position:absolute;top:14px;left:50%;transform:translateX(-50%);background:#101812e8;color:#eff7e4;border:1px solid #71844f;border-radius:24px;padding:7px 15px;font-size:12px;white-space:nowrap;opacity:0;pointer-events:none;transition:opacity .2s}.toast.show{opacity:1}.result-overlay{position:absolute;inset:0;background:#09110dcc;display:grid;place-items:center;backdrop-filter:blur(4px)}.result-overlay.hidden,.hidden{display:none!important}.result-panel{text-align:center;background:#202c24;border:1px solid #667a53;border-radius:18px;padding:22px 28px;box-shadow:0 12px 45px #0007}.result-emoji{font-size:34px}.result-panel h2{margin:4px 0;font-size:23px}.result-panel p{font-size:12px;color:var(--muted);margin:0 0 16px}.modal{width:min(92vw,450px);max-height:90vh;overflow:auto;background:#19221d;color:var(--text);border:1px solid #435346;border-radius:20px;padding:27px;box-shadow:0 20px 70px #0009}.modal::backdrop{background:#080d0acc;backdrop-filter:blur(5px)}.modal form{position:absolute}.close-modal{position:absolute;top:13px;left:15px;width:32px;height:32px;border:0;background:#263229;border-radius:10px;color:#d0dbd1;font-size:23px;line-height:1}.modal-icon{display:grid;place-items:center;background:#2b3b2b;color:var(--lime);width:45px;height:45px;border-radius:14px;font-size:26px;margin-bottom:17px}.modal h2{font-size:24px;margin:0 0 8px}.modal-desc,.privacy-note,.step-hint{font-size:12px;line-height:1.7;color:var(--muted)}.connection-actions{display:grid;grid-template-columns:1fr 1fr;gap:9px;margin-top:17px}.connection-actions button{white-space:normal;min-height:46px;font-size:12px}.connection-step{margin-top:19px;padding-top:16px;border-top:1px solid var(--line)}.connection-step label{display:block;font-size:12px;margin-bottom:8px;color:#d9e3d8}.connection-step textarea{width:100%;resize:vertical;min-height:76px;background:#101713;border:1px solid #3b4c3e;border-radius:10px;padding:10px;color:#d4edaf;font:11px ui-monospace,monospace;direction:ltr;text-align:left}.code-actions{display:flex;gap:9px;margin-top:9px}.code-actions button{flex:1}.step-hint{margin:9px 0 0}.connection-state{font-size:12px;color:var(--lime);margin-top:12px;min-height:16px}.privacy-note{font-size:10px;border-top:1px solid var(--line);padding-top:12px;margin-bottom:0}.rules-list{padding-inline-start:20px;color:#c5d0c6;font-size:13px;line-height:1.9}.rules-list li{padding-inline-start:4px;margin-bottom:5px}.full-button{width:100%;margin-top:8px}
@media(max-width:640px){.app-shell{width:calc(100% - 22px);padding-top:max(12px,env(safe-area-inset-top))}.topbar{margin-bottom:20px}.intro-row{margin-bottom:14px}.subtitle{font-size:11px}.turn-chip{font-size:10px;padding:8px 10px}.scoreboard{gap:7px}.player-card{padding:8px;gap:7px;min-height:56px;border-radius:12px}.player-avatar{width:29px;height:29px;border-radius:9px}.player-caption{font-size:9px}.player-info strong{font-size:11px}.group-tag{font-size:9px;padding:2px 6px}.score-center{min-width:51px}.score-label{font-size:9px}.score-center strong{font-size:17px}.table-card{padding:8px;border-radius:15px}.table-topline{font-size:10px;padding:1px 3px 8px}.table-footer{font-size:9px;gap:5px;padding-top:8px}.table-hint{display:none}.controls-card{gap:9px;padding:10px;border-radius:13px}.shoot-button{min-width:88px;padding:10px 12px}.reset-button{width:38px;height:38px}.bottom-tools{gap:8px}.assist-toggle{gap:7px;padding:8px;min-height:51px}.assist-copy strong{font-size:10px}.assist-copy small{font-size:8px}.assist-badge{font-size:8px;padding:3px 5px}.friend-button{white-space:normal;font-size:10px;line-height:1.4;padding:10px;max-width:45%;min-height:51px}.fair-play-note{font-size:9px}.modal{padding:23px 20px}.connection-actions{grid-template-columns:1fr}}
@media(max-width:390px){.brand{font-size:15px}.intro-row h1{font-size:26px}.turn-chip{gap:5px}.player-card{gap:5px}.player-avatar{width:25px;height:25px}.group-tag{display:none}.assist-copy small{max-width:135px}.table-footer .footer-dot{display:none}}

(() => {
  const canvas = document.getElementById('poolCanvas');
  const ctx = canvas.getContext('2d');
  const W = 1000, H = 560, R = 13, left = 62, right = 938, top = 62, bottom = 498;
  const pockets = [[left,top],[W/2,top],[right,top],[left,bottom],[W/2,bottom],[right,bottom]];
  const $ = id => document.getElementById(id);
  const ui = {turn:$('turnLabel'),status:$('statusText'),mode:$('modeLabel'),p1:$('playerOneCard'),p2:$('playerTwoCard'),n1:$('playerOneName'),n2:$('playerTwoName'),g1:$('groupOne'),g2:$('groupTwo'),s1:$('scoreOne'),s2:$('scoreTwo'),power:$('powerSlider'),powerValue:$('powerValue'),shoot:$('shootBtn'),toast:$('toast'),assist:$('assistToggle'),assistWrap:$('assistWrap'),note:$('fairPlayNote'),overlay:$('resultOverlay')};
  const game={balls:[],turn:0,groups:[null,null],scores:[0,0],ballInHand:true,moving:false,gameOver:false,aim:0,firstContact:null,shotPockets:[],scratch:false,remoteShot:false,online:false,localPlayer:0,channel:null,peer:null,sound:true,shotCount:0};
  let raf=0, toastTimer=0, pointer={x:690,y:280};

  function makeRack(){
    const balls=[{id:0,type:'cue',x:260,y:H/2,vx:0,vy:0,potted:false}];
    let id=1; const order=[1,9,2,10,8,3,11,4,12,5,13,6,14,7,15];
    for(let row=0;row<5;row++)for(let col=0;col<=row;col++){
      const n=order[id-1], x=690+row*23.5, y=H/2+(col-row/2)*27.3;
      balls.push({id:n,type:n===8?'eight':n<=7?'solid':'stripe',x,y,vx:0,vy:0,potted:false});id++;
    }
    game.balls=balls;game.turn=0;game.groups=[null,null];game.ballInHand=true;game.moving=false;game.gameOver=false;game.firstContact=null;game.shotPockets=[];game.scratch=false;game.shotCount=0;ui.overlay.classList.add('hidden');setStatus('الكرة البيضاء في يدك');updateUI();draw();
  }
  function resize(){const dpr=Math.min(window.devicePixelRatio||1,2),box=canvas.getBoundingClientRect();canvas.width=Math.round(box.width*dpr);canvas.height=Math.round(box.width*(H/W)*dpr);ctx.setTransform(canvas.width/W,0,0,canvas.height/H,0,0);draw()}
  function setStatus(s){ui.status.textContent=s}
  function showToast(s){ui.toast.textContent=s;ui.toast.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>ui.toast.classList.remove('show'),2100)}
  function updateUI(){
    ui.turn.textContent=game.turn===game.localPlayer?'دورك الآن':game.online?'دور صديقك':'دور اللاعب '+(game.turn+1);
    ui.p1.classList.toggle('active',game.turn===0);ui.p2.classList.toggle('active',game.turn===1);
    ui.s1.textContent=game.scores[0];ui.s2.textContent=game.scores[1];
    ui.g1.textContent=game.groups[0]?(game.groups[0]==='solid'?'مصمتة':'مخططة'):'—';ui.g2.textContent=game.groups[1]?(game.groups[1]==='solid'?'مصمتة':'مخططة'):'—';
    ui.shoot.disabled=game.moving||game.gameOver||(game.online&&game.turn!==game.localPlayer);
    ui.assist.disabled=game.online;ui.assistWrap.classList.toggle('disabled',game.online);
    ui.mode.textContent=game.online?'مباراة مباشرة · عادلة':'لعب محلي';
    ui.note.textContent=game.online?'في المباراة المباشرة، يستخدم كلا الهاتفين خط التصويب القياسي نفسه.':'المساعدة الطويلة تدريبية ومحلية فقط؛ لا تعمل في المباراة المباشرة.';
  }
  function activeCue(){return game.balls.find(b=>b.type==='cue'&&!b.potted)}
  function isMoving(){return game.balls.some(b=>!b.potted&&Math.hypot(b.vx,b.vy)>.045)}
  function groupsRemaining(player){const group=game.groups[player];if(!group)return 0;return game.balls.filter(b=>!b.potted&&b.type===group).length}
  function drawTable(){
    ctx.clearRect(0,0,W,H);
    ctx.fillStyle='#0b130e';ctx.fillRect(0,0,W,H);
    // warm carved rails and the felt
    rounded(ctx,14,14,W-28,H-28,28,'#5b3924');rounded(ctx,27,27,W-54,H-54,24,'#98643c');
    rounded(ctx,46,46,W-92,H-92,18,'#143b2b');
    // felt shading
    const grad=ctx.createLinearGradient(80,60,900,500);grad.addColorStop(0,'#1c5940');grad.addColorStop(.55,'#145037');grad.addColorStop(1,'#0e422f');
    rounded(ctx,left,top,right-left,bottom-top,10,grad);
    ctx.strokeStyle='#76a27b24';ctx.lineWidth=2;ctx.strokeRect(left+12,top+12,right-left-24,bottom-top-24);
    // diamonds
    for(let i=1;i<8;i++){const x=left+(right-left)*i/8;diamond(x,35,5)}
    for(let i=1;i<4;i++){const y=top+(bottom-top)*i/4;diamond(35,y,5);diamond(W-35,y,5)}
    pockets.forEach(([x,y])=>{ctx.beginPath();ctx.arc(x,y,24,0,Math.PI*2);ctx.fillStyle='#07100c';ctx.fill();ctx.beginPath();ctx.arc(x,y,18,0,Math.PI*2);ctx.fillStyle='#0a120e';ctx.fill()});
    // head string, only subtle
    ctx.strokeStyle='#d9e5d21c';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(420,top+8);ctx.lineTo(420,bottom-8);ctx.stroke();
  }
  function rounded(c,x,y,w,h,r,color){c.beginPath();c.roundRect(x,y,w,h,r);c.fillStyle=color;c.fill()}
  function diamond(x,y,r){ctx.beginPath();ctx.moveTo(x,y-r);ctx.lineTo(x+r,y);ctx.lineTo(x,y+r);ctx.lineTo(x-r,y);ctx.closePath();ctx.fillStyle='#dfbd82';ctx.fill()}
  function drawBall(b){
    if(b.potted)return;
    ctx.save();ctx.translate(b.x,b.y);
    ctx.beginPath();ctx.ellipse(2,5,R*1.03,R*.72,0,0,Math.PI*2);ctx.fillStyle='#06120c66';ctx.fill();
    ctx.beginPath();ctx.arc(0,0,R,0,Math.PI*2);ctx.fillStyle=b.type==='cue'?'#f4f1dc':b.type==='eight'?'#101113':ballColor(b.id);ctx.fill();
    if(b.type==='stripe'){ctx.save();ctx.beginPath();ctx.arc(0,0,R-.2,0,Math.PI*2);ctx.clip();ctx.fillStyle='#fff5df';ctx.fillRect(-R,-7,R*2,14);ctx.restore()}
    const shine=ctx.createRadialGradient(-5,-6,1,1,1,R*1.3);shine.addColorStop(0,'#ffffff8b');shine.addColorStop(.35,'#ffffff16');shine.addColorStop(1,'#00000035');ctx.beginPath();ctx.arc(0,0,R,0,Math.PI*2);ctx.fillStyle=shine;ctx.fill();
    if(b.type!=='cue'){
      ctx.beginPath();ctx.arc(0,0,6.2,0,Math.PI*2);ctx.fillStyle='#fff9ea';ctx.fill();ctx.fillStyle='#19201c';ctx.font='bold 8px sans-serif';ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText(String(b.id),0,.4);
    }else{ctx.beginPath();ctx.arc(-3,-4,2.1,0,Math.PI*2);ctx.fillStyle='#fff';ctx.fill()}
    ctx.restore();
  }
  function ballColor(id){return ({1:'#e4c745',2:'#4475b9',3:'#bd4339',4:'#78449a',5:'#df793d',6:'#398454',7:'#8d3037',9:'#e4c745',10:'#4475b9',11:'#bd4339',12:'#78449a',13:'#df793d',14:'#398454',15:'#8d3037'})[id]||'#fff'}
  function drawGuide(){const cue=activeCue();if(!cue||game.moving||game.gameOver)return;let dx=Math.cos(game.aim),dy=Math.sin(game.aim);
    const long=ui.assist.checked&&!game.online;
    ctx.save();ctx.lineCap='round';
    if(long){
      let x=cue.x,y=cue.y,remaining=850;ctx.strokeStyle='#e7ffd1cc';ctx.lineWidth=2;ctx.setLineDash([9,7]);ctx.beginPath();ctx.moveTo(x,y);
      for(let bounces=0;bounces<4&&remaining>0;bounces++){
        let t=remaining;let side='';
        if(dx>0&&x+dx*t>right-R){t=(right-R-x)/dx;side='x'}else if(dx<0&&x+dx*t<left+R){t=(left+R-x)/dx;side='x'}
        if(dy>0&&y+dy*t>bottom-R){const ty=(bottom-R-y)/dy;if(ty<t){t=ty;side='y'}}else if(dy<0&&y+dy*t<top+R){const ty=(top+R-y)/dy;if(ty<t){t=ty;side='y'}}
        const obstacle=nearestBall(x,y,dx,dy,t);if(obstacle){t=obstacle.distance;}
        x+=dx*t;y+=dy*t;ctx.lineTo(x,y);remaining-=t;
        if(obstacle){ctx.stroke();ctx.setLineDash([]);ctx.fillStyle='#c8f36a';ctx.beginPath();ctx.arc(x,y,5,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#c8f36a99';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(x,y);ctx.lineTo(x+dx*90,y+dy*90);ctx.stroke();ctx.restore();return}
        if(!side)break; if(side==='x')dx=-dx;else dy=-dy; x+=dx*.5;y+=dy*.5;ctx.moveTo(x,y);
      }
      ctx.stroke();ctx.restore();return;
    }
    const hit=nearestBall(cue.x,cue.y,dx,dy,155);const len=hit?hit.distance:155;
    ctx.setLineDash([7,6]);ctx.strokeStyle='#f6f7dfb0';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(cue.x,cue.y);ctx.lineTo(cue.x+dx*len,cue.y+dy*len);ctx.stroke();ctx.setLineDash([]);
    if(hit){ctx.beginPath();ctx.arc(cue.x+dx*len,cue.y+dy*len,R,0,Math.PI*2);ctx.strokeStyle='#d4edaf88';ctx.lineWidth=1.5;ctx.stroke()}
    // cue stick hint
    ctx.globalAlpha=.72;ctx.strokeStyle='#d5b17b';ctx.lineWidth=4;ctx.beginPath();ctx.moveTo(cue.x-dx*25,cue.y-dy*25);ctx.lineTo(cue.x-dx*88,cue.y-dy*88);ctx.stroke();ctx.restore();
  }
  function nearestBall(x,y,dx,dy,max){let best=null;for(const b of game.balls){if(b.potted||b.type==='cue')continue;const ox=b.x-x,oy=b.y-y,proj=ox*dx+oy*dy;if(proj<=0||proj>max)continue;const perp=Math.abs(ox*dy-oy*dx);if(perp<R*2&&(!best||proj<best.distance))best={ball:b,distance:Math.max(0,proj-Math.sqrt(Math.max(0,(R*2)**2-perp**2)))}}return best}
  function draw(){drawTable();drawGuide();for(const b of game.balls)drawBall(b);if(game.ballInHand&&!game.moving&&!game.gameOver){const c=activeCue();if(c){ctx.beginPath();ctx.arc(c.x,c.y,R+5,0,Math.PI*2);ctx.strokeStyle='#d9f9a799';ctx.setLineDash([4,4]);ctx.stroke();ctx.setLineDash([])}}}

function shoot(){if(game.moving||game.gameOver||(game.online&&game.turn!==game.localPlayer))return;const cue=activeCue();if(!cue)return;
  const p=Number(ui.power.value)/100,force=2.2+p*15.8;cue.vx=Math.cos(game.aim)*force;cue.vy=Math.sin(game.aim)*force;game.moving=true;game.firstContact=null;game.shotPockets=[];game.scratch=false;game.ballInHand=false;game.remoteShot=false;game.shotCount++;setStatus('الكرات تتحرك…');updateUI();playSound('hit');
  if(game.online)send({type:'shot',angle:game.aim,power:p,shooter:game.turn});tick();
}
function tick(){if(!game.moving)return;let still=true;
  for(const b of game.balls){if(b.potted)continue;b.x+=b.vx;b.y+=b.vy;b.vx*=.985;b.vy*=.985;if(Math.abs(b.vx)<.035)b.vx=0;if(Math.abs(b.vy)<.035)b.vy=0;if(Math.hypot(b.vx,b.vy)>.045)still=false;
    if((b.x-left)**2+(b.y-top)**2<27**2||(b.x-W/2)**2+(b.y-top)**2<23**2||(b.x-right)**2+(b.y-top)**2<27**2||(b.x-left)**2+(b.y-bottom)**2<27**2||(b.x-W/2)**2+(b.y-bottom)**2<23**2||(b.x-right)**2+(b.y-bottom)**2<27**2){b.potted=true;b.vx=b.vy=0;game.shotPockets.push(b.type);if(b.type==='cue')game.scratch=true;playSound('drop');continue}
    if(b.x<left+R){b.x=left+R;b.vx=Math.abs(b.vx)*.91;playSound('rail')}if(b.x>right-R){b.x=right-R;b.vx=-Math.abs(b.vx)*.91;playSound('rail')}if(b.y<top+R){b.y=top+R;b.vy=Math.abs(b.vy)*.91;playSound('rail')}if(b.y>bottom-R){b.y=bottom-R;b.vy=-Math.abs(b.vy)*.91;playSound('rail')}
  }
  for(let i=0;i<game.balls.length;i++){const a=game.balls[i];if(a.potted)continue;for(let j=i+1;j<game.balls.length;j++){const b=game.balls[j];if(b.potted)continue;let dx=b.x-a.x,dy=b.y-a.y,d=Math.hypot(dx,dy);if(d===0){dx=.01;d=.01}if(d<R*2){if(!game.firstContact){if(a.type==='cue')game.firstContact=b.type;else if(b.type==='cue')game.firstContact=a.type}
    const nx=dx/d,ny=dy/d,overlap=R*2-d;a.x-=nx*overlap/2;a.y-=ny*overlap/2;b.x+=nx*overlap/2;b.y+=ny*overlap/2;
    const rel=(a.vx-b.vx)*nx+(a.vy-b.vy)*ny;if(rel>0){const impulse=rel*.96;a.vx-=impulse*nx;a.vy-=impulse*ny;b.vx+=impulse*nx;b.vy+=impulse*ny}still=false;
  }}}
  draw();
  if(!still||isMoving()){raf=requestAnimationFrame(tick);return}
  game.moving=false;finishShot();updateUI();draw();
}
function finishShot(){
  const shooter=game.turn, own=game.groups[shooter], other=game.groups[1-shooter];
  const first=game.firstContact;let foul=game.scratch||!first;
  if(first){if(first==='eight'){if(own&&groupsRemaining(shooter)>0)foul=true}
    else if(own&&first!==own)foul=true;
  }
  let pottedOwn=0,pottedOther=0;
  if(!own&&!game.groups[shooter]){
    const firstGroup=game.shotPockets.find(x=>x==='solid'||x==='stripe');if(firstGroup){game.groups[shooter]=firstGroup;game.groups[1-shooter]=firstGroup==='solid'?'stripe':'solid'}
  }
  if(game.groups[shooter])for(const type of game.shotPockets){if(type===game.groups[shooter])pottedOwn++;if(type===game.groups[1-shooter])pottedOther++}
  const eightDown=game.shotPockets.includes('eight');
  if(eightDown){const cleared=own?groupsRemaining(shooter)<=pottedOwn: false;const win=!foul&&cleared;endGame(win?shooter:1-shooter,win?'أسقطت الكرة 8 بعد إنهاء مجموعتك.':'الكرة 8 دخلت مبكراً أو مع خطأ.');return}
  if(foul){game.turn=1-shooter;game.ballInHand=true;const cue=activeCue();if(cue){cue.x=260;cue.y=H/2;cue.vx=cue.vy=0}setStatus(game.scratch?'خطأ: الكرة البيضاء دخلت الجيب. حرّكها ثم العب.':'خطأ في التصويب. الكرة البيضاء في يد الخصم.');showToast(game.scratch?'خطأ! البيضاء دخلت الجيب':'خطأ! دور الخصم مع الكرة في يده');}
  else if(game.shotPockets.length===0){game.turn=1-shooter;setStatus('لم تدخل كرة. دور الخصم.');}
  else{game.turn=shooter;setStatus(game.groups[shooter]?'أحسنت! أكمل مجموعتك.':'أحسنت! اخترت مجموعتك.');showToast(game.groups[shooter]?'كرة في الجيب — دورك مستمر':'تم تحديد المجموعات');}
  game.shotPockets=[];
  if(game.online&&!game.remoteShot)send({type:'snapshot',state:exportState()});game.remoteShot=false;
}
function endGame(winner,message){game.gameOver=true;game.turn=winner;game.scores[winner]++;setStatus(winner===game.localPlayer?'فزت بالجولة!':'انتهت الجولة');$('resultTitle').textContent=game.online?(winner===game.localPlayer?'فزت!':'صديقك فاز!'):(winner===0?'اللاعب الأول فاز!':'اللاعب الثاني فاز!');$('resultMessage').textContent=message;ui.overlay.classList.remove('hidden');if(game.online&&!game.remoteShot)send({type:'snapshot',state:exportState()});game.remoteShot=false;updateUI()}
function exportState(){return {balls:game.balls,turn:game.turn,groups:game.groups,scores:game.scores,ballInHand:game.ballInHand,moving:game.moving,gameOver:game.gameOver,aim:game.aim}}
function applyState(s){if(!s)return;game.balls=s.balls;game.turn=s.turn;game.groups=s.groups;game.scores=s.scores;game.ballInHand=s.ballInHand;game.moving=s.moving;game.gameOver=s.gameOver;game.aim=s.aim||0;game.shotPockets=[];game.firstContact=null;if(game.gameOver){$('resultTitle').textContent=game.turn===game.localPlayer?'فزت!':'صديقك فاز!';$('resultMessage').textContent='انتهت الجولة.';ui.overlay.classList.remove('hidden')}else ui.overlay.classList.add('hidden');setStatus(game.moving?'الكرات تتحرك…':game.ballInHand?'الكرة البيضاء في يدك':'اختر اتجاه الضربة');updateUI();draw();if(game.moving)tick()}
function placeCue(x,y){const cue=activeCue();if(!cue)return; x=Math.max(left+R+2,Math.min(right-R-2,x));y=Math.max(top+R+2,Math.min(bottom-R-2,y));if(game.balls.some(b=>!b.potted&&b!==cue&&Math.hypot(b.x-x,b.y-y)<R*2+2)){showToast('المكان مزدحم، اختر نقطة أخرى');return}cue.x=x;cue.y=y;game.ballInHand=false;setStatus('وجّه العصا واضبط القوة');draw()}

canvas.addEventListener('pointermove',e=>{const r=canvas.getBoundingClientRect();pointer.x=(e.clientX-r.left)/r.width*W;pointer.y=(e.clientY-r.top)/r.height*H;const cue=activeCue();if(cue&&!game.moving&&!game.gameOver&&!game.ballInHand){game.aim=Math.atan2(pointer.y-cue.y,pointer.x-cue.x);draw()}});
canvas.addEventListener('pointerdown',e=>{if(game.moving||game.gameOver||(game.online&&game.turn!==game.localPlayer))return;const r=canvas.getBoundingClientRect(),x=(e.clientX-r.left)/r.width*W,y=(e.clientY-r.top)/r.height*H;if(game.ballInHand){placeCue(x,y);e.preventDefault();return}const cue=activeCue();if(cue){game.aim=Math.atan2(y-cue.y,x-cue.x);draw()}e.preventDefault()});
$('powerSlider').addEventListener('input',()=>{ui.powerValue.textContent=Math.round(ui.power.value/10)+'٪'});
ui.shoot.addEventListener('click',shoot);$('rackBtn').addEventListener('click',()=>{if(game.online){showToast('الجولة الجديدة تبدأ بعد إعادة المباراة');return}makeRack();showToast('تم ترتيب الكرات')});$('rematchBtn').addEventListener('click',()=>{makeRack();if(game.online)send({type:'new-game'})});
ui.assist.addEventListener('change',()=>draw());
$('soundBtn').addEventListener('click',()=>{game.sound=!game.sound;$('soundIcon').textContent=game.sound?'♪':'♩';showToast(game.sound?'الصوت يعمل':'الصوت مكتوم')});
$('friendBtn').addEventListener('click',()=>{$('friendDialog').showModal();resetConnectionUI()});$('rulesBtn').addEventListener('click',()=>$('rulesDialog').showModal());$('closeRulesBtn').addEventListener('click',()=>$('rulesDialog').close());
$('powerValue').textContent='٥٥٪';
function playSound(kind){if(!game.sound)return;try{const AC=window.AudioContext||window.webkitAudioContext;if(!playSound.ac)playSound.ac=new AC();const a=playSound.ac;if(a.state==='suspended')a.resume();const osc=a.createOscillator(),gain=a.createGain();osc.connect(gain);gain.connect(a.destination);const now=a.currentTime;const freq=kind==='hit'?190:kind==='drop'?280:kind==='rail'?110:200;osc.frequency.setValueAtTime(freq,now);osc.frequency.exponentialRampToValueAtTime(freq*.56,now+.07);gain.gain.setValueAtTime(kind==='hit'?.035:.018,now);gain.gain.exponentialRampToValueAtTime(.001,now+.08);osc.start(now);osc.stop(now+.085)}catch(_){}}

  // Direct phone-to-phone connection. The offer/answer is exchanged out-of-band by the players.
  const friendDialog=$('friendDialog'), connectionStep=$('connectionStep'), connectionCode=$('connectionCode'), connectionState=$('connectionState'), stepHint=$('stepHint'), codeLabel=$('codeLabel');
  let connectionRole='',connectionStage='',pendingDesc=null;
  function resetConnectionUI(){connectionStep.classList.add('hidden');connectionCode.value='';connectionState.textContent='';$('createRoomBtn').disabled=false;$('joinRoomBtn').disabled=false;connectionRole='';connectionStage='';if(game.online&&game.channel?.readyState==='open')connectionState.textContent='متصل بصديقك الآن.'}
  async function waitIce(pc){if(pc.iceGatheringState==='complete')return;await new Promise(resolve=>{const done=()=>{if(pc.iceGatheringState==='complete'){pc.removeEventListener('icegatheringstatechange',done);resolve()}};pc.addEventListener('icegatheringstatechange',done);setTimeout(resolve,9000)})}
  function newPeer(isHost){game.peer=new RTCPeerConnection({iceServers:[{urls:'stun:stun.l.google.com:19302'},{urls:'stun:stun1.l.google.com:19302'}]});game.peer.onconnectionstatechange=()=>{if(['failed','disconnected','closed'].includes(game.peer?.connectionState))connectionState.textContent='انقطع الاتصال. قد تمنع الشبكة الاتصال المباشر.'};if(isHost){game.channel=game.peer.createDataChannel('pool-match',{ordered:true});bindChannel(game.channel)}else game.peer.ondatachannel=e=>{game.channel=e.channel;bindChannel(game.channel)};}
  function bindChannel(channel){channel.onopen=()=>{connectionState.textContent='تم الاتصال! دوركما يبدأ الآن.';game.online=true;game.localPlayer=connectionRole==='host'?0:1;game.turn=0;game.ballInHand=true;$('playerOneName').textContent=game.localPlayer===0?'أنت':'صديقك';$('playerTwoName').textContent=game.localPlayer===1?'أنت':'صديقك';ui.assist.checked=false;updateUI();if(connectionRole==='host')send({type:'snapshot',state:exportState()});else send({type:'ready'});showToast('اتصال مباشر — استمتعوا باللعب!');setTimeout(()=>friendDialog.close(),950)};
    channel.onmessage=e=>{let m;try{m=JSON.parse(e.data)}catch(_){return}if(m.type==='shot'){if(m.shooter!==game.turn||game.moving)return;game.aim=m.angle;const cue=activeCue();if(!cue)return;cue.vx=Math.cos(m.angle)*(2.2+m.power*15.8);cue.vy=Math.sin(m.angle)*(2.2+m.power*15.8);game.moving=true;game.firstContact=null;game.shotPockets=[];game.scratch=false;game.ballInHand=false;game.remoteShot=true;game.shotCount++;setStatus('الكرات تتحرك…');updateUI();tick()}else if(m.type==='snapshot'){applyState(m.state)}else if(m.type==='new-game'){makeRack()}};
  }
  function send(message){if(game.channel?.readyState==='open')game.channel.send(JSON.stringify(message))}
  $('createRoomBtn').addEventListener('click',async()=>{if(!window.RTCPeerConnection){connectionState.textContent='المتصفح لا يدعم الاتصال المباشر.';return}try{connectionRole='host';connectionStage='host-answer';connectionState.textContent='جارٍ إنشاء رمز الدعوة…';newPeer(true);const offer=await game.peer.createOffer();await game.peer.setLocalDescription(offer);await waitIce(game.peer);connectionCode.value=JSON.stringify(game.peer.localDescription);codeLabel.textContent='١. أرسل رمز الدعوة لصديقك. بعد أن يرسل لك رمز الرد، الصقه هنا.';stepHint.textContent='بعد نسخ الدعوة، اطلب من صديقك اختيار «لديّ رمز دعوة» على هاتفه.';connectionStep.classList.remove('hidden');connectionState.textContent='تم إنشاء الدعوة. انسخها وشاركها مع صديقك.';$('createRoomBtn').disabled=true;$('joinRoomBtn').disabled=true}catch(e){connectionState.textContent='تعذر إنشاء الاتصال: '+e.message}});
  $('joinRoomBtn').addEventListener('click',()=>{connectionRole='guest';connectionStage='guest-offer';connectionStep.classList.remove('hidden');connectionCode.value='';codeLabel.textContent='الصق رمز الدعوة الذي أرسله صديقك.';stepHint.textContent='بعد متابعة الخطوة، انسخ رمز الرد وأرسله لصاحب الدعوة.';$('createRoomBtn').disabled=true;$('joinRoomBtn').disabled=true;connectionState.textContent='أدخل رمز الدعوة للمتابعة.'});
  $('continueCodeBtn').addEventListener('click',async()=>{try{const desc=JSON.parse(connectionCode.value.trim());if(connectionStage==='guest-offer'){newPeer(false);await game.peer.setRemoteDescription(desc);const answer=await game.peer.createAnswer();await game.peer.setLocalDescription(answer);await waitIce(game.peer);connectionCode.value=JSON.stringify(game.peer.localDescription);connectionStage='guest-answer';codeLabel.textContent='أرسل رمز الرد إلى صديقك صاحب الدعوة.';stepHint.textContent='سيتم الاتصال تلقائياً بعد أن يضيف صديقك رمز الرد.';connectionState.textContent='تم إنشاء رمز الرد — انسخه وأرسله.';$('continueCodeBtn').textContent='تم، أنتظر الاتصال';$('continueCodeBtn').onclick=()=>{connectionState.textContent='بانتظار صاحب الدعوة…'};return}
      if(connectionStage==='guest-answer'){connectionState.textContent='بانتظار الاتصال…';return}
      if(connectionStage==='host-answer'){await game.peer.setRemoteDescription(desc);connectionState.textContent='تم استلام الرد. جارٍ الاتصال…';return}
    }catch(e){connectionState.textContent='الرمز غير صالح أو تعذر الاتصال. تأكد من نسخه كاملاً.'}});
  $('copyCodeBtn').addEventListener('click',async()=>{try{await navigator.clipboard.writeText(connectionCode.value);connectionState.textContent='تم نسخ الرمز إلى الحافظة.'}catch(_){connectionCode.focus();connectionCode.select();connectionState.textContent='حدد النص وانسخه يدوياً.'}});
  // Input on host advances with a pasted answer; guests generate their response only once.
  $('connectionCode').addEventListener('focus',()=>{});
  $('newGameBtn')?.addEventListener('click',makeRack);
  window.addEventListener('resize',resize);window.addEventListener('orientationchange',()=>setTimeout(resize,160));
  makeRack();resize();
})();

