function finishShot(){const shooter=game.turn,own=game.groups[shooter];let foul=game.scratch||!game.firstContact;if(game.firstContact){if(game.firstContact==='eight'&&own&&groupsRemaining(shooter)>0)foul=true;else if(game.firstContact!=='eight'&&own&&game.firstContact!==own)foul=true}if(!own){const firstGroup=game.shotPockets.find(x=>x==='solid'||x==='stripe');if(firstGroup){game.groups[shooter]=firstGroup;game.groups[1-shooter]=firstGroup==='solid'?'stripe':'solid'}}const pottedOwn=game.shotPockets.filter(x=>x===game.groups[shooter]).length,eightDown=game.shotPockets.includes('eight');if(eightDown){const cleared=own?groupsRemaining(shooter)<=pottedOwn:false;const won=!foul&&cleared;endGame(won?shooter:1-shooter,won?'أسقطت الكرة 8 بعد إنهاء مجموعتك.':'الكرة 8 دخلت مبكراً أو مع خطأ.');return}if(foul){game.turn=1-shooter;game.ballInHand=true;let cue=activeCue();if(!cue){cue=game.balls.find(b=>b.type==='cue');cue.potted=false}cue.x=260;cue.y=H/2;cue.vx=cue.vy=0;setStatus(game.scratch?'خطأ: البيضاء دخلت الجيب. حرّكها ثم العب.':'خطأ في التصويب. الكرة البيضاء في يد الخصم.');showToast('خطأ! دور الخصم مع الكرة في يده')}else if(!game.shotPockets.length){game.turn=1-shooter;setStatus('لم تدخل كرة. دور الخصم.')}else{game.turn=shooter;setStatus(game.groups[shooter]?'أحسنت! أكمل مجموعتك.':'أحسنت! اخترت مجموعتك.');showToast(game.groups[shooter]?'كرة في الجيب — دورك مستمر':'تم تحديد المجموعات')}game.shotPockets=[];if(game.online&&!game.remoteShot)send({type:'snapshot',state:exportState()});game.remoteShot=false}
function endGame(winner,message){game.gameOver=true;game.turn=winner;game.scores[winner]++;setStatus('انتهت الجولة');$('resultTitle').textContent=game.online?(winner===game.localPlayer?'فزت!':'صديقك فاز!'):(winner===0?'اللاعب الأول فاز!':'اللاعب الثاني فاز!');$('resultMessage').textContent=message;ui.overlay.classList.remove('hidden');if(game.online&&!game.remoteShot)send({type:'snapshot',state:exportState()});game.remoteShot=false;updateUI()}
function exportState(){return{balls:game.balls,turn:game.turn,groups:game.groups,scores:game.scores,ballInHand:game.ballInHand,moving:game.moving,gameOver:game.gameOver,aim:game.aim}}
function applyState(s){if(!s)return;game.balls=s.balls;game.turn=s.turn;game.groups=s.groups;game.scores=s.scores;game.ballInHand=s.ballInHand;game.moving=s.moving;game.gameOver=s.gameOver;game.aim=s.aim||0;game.shotPockets=[];game.firstContact=null;if(game.gameOver){$('resultTitle').textContent=game.turn===game.localPlayer?'فزت!':'صديقك فاز!';$('resultMessage').textContent='انتهت الجولة.';ui.overlay.classList.remove('hidden')}else ui.overlay.classList.add('hidden');setStatus(game.moving?'الكرات تتحرك…':game.ballInHand?'الكرة البيضاء في يدك':'اختر اتجاه الضربة');updateUI();draw();if(game.moving)tick()}
function placeCue(x,y){let cue=activeCue();if(!cue){cue=game.balls.find(b=>b.type==='cue');cue.potted=false}x=Math.max(left+R+2,Math.min(right-R-2,x));y=Math.max(top+R+2,Math.min(bottom-R-2,y));if(game.balls.some(b=>!b.potted&&b!==cue&&Math.hypot(b.x-x,b.y-y)<R*2+2)){showToast('المكان مزدحم، اختر نقطة أخرى');return}cue.x=x;cue.y=y;cue.vx=cue.vy=0;game.ballInHand=false;setStatus('وجّه العصا واضبط القوة');draw()}
canvas.addEventListener('pointermove',e=>{const r=canvas.getBoundingClientRect(),x=(e.clientX-r.left)/r.width*W,y=(e.clientY-r.top)/r.height*H,cue=activeCue();if(cue&&!game.moving&&!game.gameOver&&!game.ballInHand){game.aim=Math.atan2(y-cue.y,x-cue.x);draw()}});
canvas.addEventListener('pointerdown',e=>{if(game.moving||game.gameOver||(game.online&&game.turn!==game.localPlayer))return;const r=canvas.getBoundingClientRect(),x=(e.clientX-r.left)/r.width*W,y=(e.clientY-r.top)/r.height*H;if(game.ballInHand)placeCue(x,y);else{const cue=activeCue();if(cue){game.aim=Math.atan2(y-cue.y,x-cue.x);draw()}}e.preventDefault()});
ui.power.addEventListener('input',()=>{ui.powerValue.textContent=Number(ui.power.value).toLocaleString('ar')+'٪'});ui.shoot.addEventListener('click',shoot);$('rackBtn').addEventListener('click',()=>{if(game.online){showToast('استخدم جولة جديدة بعد انتهاء المباراة');return}makeRack();showToast('تم ترتيب الكرات')});$('rematchBtn').addEventListener('click',()=>{makeRack();if(game.online)send({type:'new-game'})});ui.assist.addEventListener('change',draw);
$('soundBtn').addEventListener('click',()=>{game.sound=!game.sound;$('soundIcon').textContent=game.sound?'♪':'♩';showToast(game.sound?'الصوت يعمل':'الصوت مكتوم')});$('friendBtn').addEventListener('click',()=>{$('friendDialog').showModal();resetConnectionUI()});$('rulesBtn').addEventListener('click',()=>$('rulesDialog').showModal());$('closeRulesBtn').addEventListener('click',()=>$('rulesDialog').close());
function playSound(kind){if(!game.sound)return;try{const AC=window.AudioContext||window.webkitAudioContext;if(!playSound.ac)playSound.ac=new AC();const a=playSound.ac;if(a.state==='suspended')a.resume();const osc=a.createOscillator(),gain=a.createGain();osc.connect(gain);gain.connect(a.destination);const now=a.currentTime,freq=kind==='hit'?190:kind==='drop'?280:kind==='rail'?110:200;osc.frequency.setValueAtTime(freq,now);osc.frequency.exponentialRampToValueAtTime(freq*.56,now+.07);gain.gain.setValueAtTime(kind==='hit'?.035:.018,now);gain.gain.exponentialRampToValueAtTime(.001,now+.08);osc.start(now);osc.stop(now+.085)}catch(_){}}

