  function playSound(kind){if(!game.sound)return;try{const AC=window.AudioContext||window.webkitAudioContext;if(!playSound.ac)playSound.ac=new AC();const a=playSound.ac;if(a.state==='suspended')a.resume();const osc=a.createOscillator(),gain=a.createGain();osc.connect(gain);gain.connect(a.destination);const now=a.currentTime,freq=kind==='hit'?190:kind==='drop'?280:kind==='rail'?110:200;osc.frequency.setValueAtTime(freq,now);osc.frequency.exponentialRampToValueAtTime(freq*.56,now+.07);gain.gain.setValueAtTime(kind==='hit'?.035:.018,now);gain.gain.exponentialRampToValueAtTime(.001,now+.08);osc.start(now);osc.stop(now+.085)}catch(_){}}
  let connectionRole='',connectionPhase='';
  const friendDialog=$('friendDialog'),connectionStep=$('connectionStep'),connectionCode=$('connectionCode');
  function resetConnectionUI(){connectionStep.classList.add('hidden');$('connectionState').textContent='';$('createRoomBtn').disabled=false;$('joinRoomBtn').disabled=false;connectionCode.value='';connectionRole='';connectionPhase='';if(game.peer&&game.peer.connectionState!=='connected'){game.peer.close();game.peer=null;game.channel=null}}
  function connectionMessage(text){$('connectionState').textContent=text}
  function showConnectionStep(role,phase){connectionRole=role;connectionPhase=phase;connectionStep.classList.remove('hidden');$('createRoomBtn').disabled=true;$('joinRoomBtn').disabled=true;$('continueCodeBtn').disabled=false}
  function waitForIce(pc){if(pc.iceGatheringState==='complete')return Promise.resolve();return new Promise(resolve=>{const done=()=>{if(pc.iceGatheringState==='complete'){pc.removeEventListener('icegatheringstatechange',done);resolve()}};pc.addEventListener('icegatheringstatechange',done);setTimeout(resolve,12000)})}
  function encodeDescription(desc){return JSON.stringify({type:desc.type,sdp:desc.sdp})}
  function setStep(role,phase,label,hint,button){showConnectionStep(role,phase);$('codeLabel').textContent=label;$('stepHint').textContent=hint;$('continueCodeBtn').textContent=button}
  function setupChannel(channel){game.channel=channel;channel.onopen=()=>{game.online=true;game.localPlayer=connectionRole==='host'?0:1;ui.assist.checked=false;updateUI();draw();connectionMessage('تم الاتصال! يمكنكما بدء اللعب.');if(connectionRole==='host')send({type:'snapshot',state:exportState()})};channel.onclose=()=>{game.online=false;updateUI();connectionMessage('انقطع الاتصال. يمكنكما مواصلة اللعب محلياً.')};channel.onerror=()=>connectionMessage('حدثت مشكلة في الاتصال. جرّبوا إنشاء دعوة جديدة.');channel.onmessage=e=>{let msg;try{msg=JSON.parse(e.data)}catch(_){return}if(msg.type==='snapshot')applyState(msg.state);else if(msg.type==='shot'){if(!game.online||msg.shooter!==game.turn)return;const cue=activeCue()||game.balls.find(b=>b.type==='cue');if(!cue)return;cue.potted=false;cue.x=msg.x;cue.y=msg.y;cue.vx=Math.cos(msg.angle)*msg.force;cue.vy=Math.sin(msg.angle)*msg.force;game.aim=msg.angle;game.moving=true;game.firstContact=null;game.shotPockets=[];game.scratch=false;game.ballInHand=false;game.remoteShot=true;setStatus('الكرات تتحرك…');updateUI();tick()}else if(msg.type==='new-game'){makeRack();if(connectionRole==='host')send({type:'snapshot',state:exportState()})}}}
  function send(message){if(game.channel&&game.channel.readyState==='open'){try{game.channel.send(JSON.stringify(message))}catch(_){showToast('تعذر إرسال تحديث المباراة')}}}
  $('createRoomBtn').addEventListener('click',async()=>{if(!window.RTCPeerConnection){connectionMessage('هذا المتصفح لا يدعم الاتصال المباشر.');return}try{connectionRole='host';const pc=new RTCPeerConnection({iceServers:[{urls:'stun:stun.l.google.com:19302'}]});game.peer=pc;setupChannel(pc.createDataChannel('pool-game'));const offer=await pc.createOffer();await pc.setLocalDescription(offer);connectionMessage('جارٍ تجهيز الدعوة…');await waitForIce(pc);connectionCode.value=encodeDescription(pc.localDescription);setStep('host','host-answer','رمز الدعوة','انسخ هذا الرمز وأرسله لصديقك. بعد أن يرسل لك رمز الرد، الصقه هنا واضغط تطبيق الرمز.','تطبيق الرمز');connectionMessage('أرسل الدعوة إلى صديقك وانتظر رمز الرد.')}catch(err){connectionMessage('تعذر إنشاء الدعوة: '+err.message)}});
  $('joinRoomBtn').addEventListener('click',()=>{connectionCode.value='';setStep('join','join-offer','رمز الدعوة','الصق رمز الدعوة الذي أرسله صديقك، ثم اضغط متابعة لإنشاء رمز الرد.','متابعة');connectionCode.focus()});
  $('continueCodeBtn').addEventListener('click',async()=>{const text=connectionCode.value.trim();if(!text){connectionMessage('أدخل الرمز أولاً.');return}try{if(connectionPhase==='host-answer'){const answer=JSON.parse(text);await game.peer.setRemoteDescription(answer);connectionPhase='host-wait';$('continueCodeBtn').disabled=true;connectionMessage('تم تطبيق الرد. جارٍ الاتصال…')}else if(connectionPhase==='join-offer'){if(!window.RTCPeerConnection)throw new Error('المتصفح لا يدعم WebRTC');const offer=JSON.parse(text),pc=new RTCPeerConnection({iceServers:[{urls:'stun:stun.l.google.com:19302'}]});game.peer=pc;pc.ondatachannel=e=>setupChannel(e.channel);await pc.setRemoteDescription(offer);const answer=await pc.createAnswer();await pc.setLocalDescription(answer);connectionMessage('جارٍ تجهيز رمز الرد…');await waitForIce(pc);connectionCode.value=encodeDescription(pc.localDescription);setStep('join','join-answer','رمز الرد','أرسل هذا الرمز إلى صديقك وانتظر اكتمال الاتصال.','تم، أنتظر الاتصال');connectionMessage('أرسل رمز الرد إلى صديقك.')}else if(connectionPhase==='join-answer'){connectionMessage('أرسل رمز الرد إلى صديقك. اترك هذه النافذة مفتوحة حتى يتصل.')}}catch(err){connectionMessage('الرمز غير صالح أو تعذر تطبيقه: '+err.message)}});
  $('copyCodeBtn').addEventListener('click',async()=>{try{await navigator.clipboard.writeText(connectionCode.value);connectionMessage('تم نسخ الرمز.')}catch(_){connectionCode.focus();connectionCode.select();connectionMessage('حدد الرمز وانسخه يدوياً.')}});
  friendDialog.addEventListener('close',()=>{if(!game.online&&game.peer){game.peer.close();game.peer=null;game.channel=null}});
  window.addEventListener('resize',resize);makeRack();resize();
})();

